<?php
namespace App\Http\Controllers;
use App\Contracts\ProtectedMediaStorage;use App\Jobs\{SearchFaces,WithdrawBiometricConsent};use App\Models\{BiometricConsent,FaceSearchSubject,Group};use App\Services\Face\FaceRecognitionManager;use Illuminate\Http\Request;use Illuminate\Support\Str;
class BiometricController extends Controller{private function member(Request$r,Group$group):void{abort_unless($group->isMember($r->user())&&$group->face_recognition_enabled,403);}public function consent(Request$r,Group$group){$this->member($r,$group);$data=$r->validate(['accepted'=>'accepted','is_minor'=>'sometimes|boolean','privacy_notice_version'=>'required|string|max:30']);abort_if($r->boolean('is_minor')&&!config('face.minor_processing_enabled'),403,'Minor biometric processing is disabled.');$c=BiometricConsent::create(['uuid'=>(string)Str::uuid(),'group_id'=>$group->id,'user_id'=>$r->user()->id,'purpose'=>'event_photo_matching','privacy_notice_version'=>$data['privacy_notice_version'],'state'=>'granted','granted_at'=>now(),'ip_hash'=>hash('sha256',(string)$r->ip()),'user_agent_hash'=>hash('sha256',(string)$r->userAgent())]);\App\Models\BiometricConsentEvent::create(['biometric_consent_id'=>$c->id,'action'=>'granted','purpose'=>'event_photo_matching','consent_version'=>$c->privacy_notice_version,'actor_id'=>$r->user()->id,'created_at'=>now()]);return response()->json(['consent_uuid'=>$c->uuid,'state'=>'granted'],201);}public function search(Request$r,Group$group,ProtectedMediaStorage$s){$this->member($r,$group);$data=$r->validate(['consent_uuid'=>'required|uuid','selfie'=>'required|image|mimes:jpeg,jpg,png,webp|max:8192']);$c=BiometricConsent::where('uuid',$data['consent_uuid'])->where('group_id',$group->id)->where('user_id',$r->user()->id)->where('state','granted')->firstOrFail();$file=$r->file('selfie');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file->getRealPath());$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;abort_unless($ext,422,'Unsupported selfie type.');$key=$s->putFile(config('media.prefixes.selfies').'/groups/'.$group->id,$file,$ext);$subject=FaceSearchSubject::create(['uuid'=>(string)Str::uuid(),'biometric_consent_id'=>$c->id,'group_id'=>$group->id,'user_id'=>$r->user()->id,'storage_disk'=>$s->disk(),'object_key'=>$key,'checksum_sha256'=>$s->checksum($key),'state'=>'queued','expires_at'=>now()->addHours((int)config('face.selfie_retention_hours',24))]);SearchFaces::dispatch($subject->id);return response()->json(['search_uuid'=>$subject->uuid,'state'=>'queued'],202);}public function show(Request$r,FaceSearchSubject$s){abort_unless($s->user_id===$r->user()->id,403);return response()->json(['uuid'=>$s->uuid,'state'=>$s->state,'outcome'=>$s->outcome,'deletion_state'=>$s->deletion_state,'expires_at'=>$s->expires_at,'photos'=>$s->results()->with('asset.photo')->get()->map(fn($m)=>['photo_id'=>$m->asset->photo_id,'similarity'=>(float)$m->similarity,'review_state'=>$m->review_state])]);}public function cancel(Request$r,FaceSearchSubject$s,FaceRecognitionManager$m){abort_unless($s->user_id===$r->user()->id,403);abort_if($s->state==='completed',409);$s->update(['state'=>'cancelled']);$m->deleteSelfie($s->fresh());return response()->json(['state'=>'cancelled','deletion_state'=>'completed']);}public function withdraw(Request$r,BiometricConsent$c){abort_unless($c->user_id===$r->user()->id,403);$c->update(['state'=>'withdrawn','withdrawn_at'=>now()]);\App\Models\BiometricConsentEvent::create(['biometric_consent_id'=>$c->id,'action'=>'withdrawn','purpose'=>'event_photo_matching','consent_version'=>$c->privacy_notice_version,'actor_id'=>$r->user()->id,'created_at'=>now()]);WithdrawBiometricConsent::dispatch($c->id);return response()->json(['state'=>'withdrawn']);}}
